INSERT INTO skill_tags (key, family, country, meta) VALUES
  ('script:latin', 'script', null, '{"display":"Latin","notes":"Most widely used alphabet. Common in Europe, Americas, parts of Africa and Asia.","examples":["Hotel","Restaurant","Police"]}'::jsonb),
  ('script:devanagari:hindi', 'script', 'IN', '{"display":"Hindi (Devanagari)","notes":"Most common language in India, found in central and northern regions. Distinctive horizontal line (shirorekha) through the top of each word with straight vertical lines.","examples":["होटल","रेस्तरां","स्कूल"],"regions":["IN-DL","IN-UP","IN-MP","IN-RJ","IN-HR"]}'::jsonb),
  ('script:devanagari:marathi', 'script', 'IN', '{"display":"Marathi (Devanagari)","notes":"Found in Maharashtra. Uses Devanagari script but sometimes includes the letter ळ which is not found in Hindi.","examples":["हॉटेल","रेस्टॉरंट","शाळा","ळ"],"regions":["IN-MH"]}'::jsonb),
  ('script:gurmukhi:punjabi', 'script', 'IN', '{"display":"Punjabi (Gurmukhi)","notes":"Found in Punjab (northwestern India). Softer letter shapes than Hindi, horizontal bar broken over certain letters. Distinct characters: ਨ, ਲ, ਅ and soft curve diacritic beneath letters.","examples":["ਹੋਟਲ","ਰੈਸਟੋਰੈਂਟ","ਸਕੂਲ","ਨ","ਲ","ਅ"],"regions":["IN-PB"]}'::jsonb),
  ('script:gujarati', 'script', 'IN', '{"display":"Gujarati","notes":"Found in Gujarat. Similar to Hindi but notably lacks the horizontal line at the top of every word.","examples":["હોટલ","રેસ્ટોરન્ટ","શાળા"],"regions":["IN-GJ"]}'::jsonb),
  ('script:bengali', 'script', 'IN', '{"display":"Bengali","notes":"Found in northeastern India (West Bengal) and Bangladesh. Similar look to Devanagari but recognizable by many letters featuring left-facing triangular shapes.","examples":["হোটেল","রেস্তোরাঁ","স্কুল"],"regions":["IN-WB","BD"]}'::jsonb),
  ('script:bengali:assamese', 'script', 'IN', '{"display":"Assamese (Bengali script)","notes":"Found in Assam. Uses Bengali script with additional characters, most notably ৰ and ৱ.","examples":["হোটেল","ৰেস্তোৰাঁ","স্কুল","ৰ","ৱ"],"regions":["IN-AS"]}'::jsonb),
  ('script:kannada', 'script', 'IN', '{"display":"Kannada","notes":"Found in Karnataka. Smooth curves and small circles. Many characters feature a distinct squiggly tail in the top right corner, less common in Telugu.","examples":["ಹೋಟೆಲ್","ರೆಸ್ಟೋರೆಂಟ್","ಶಾಲೆ"],"regions":["IN-KA"]}'::jsonb),
  ('script:telugu', 'script', 'IN', '{"display":"Telugu","notes":"Found in Telangana and Andhra Pradesh. Very similar to Kannada but often has diacritics resembling checkmarks at the top of letters.","examples":["హోటల్","రెస్టారెంట్","పాఠశాల"],"regions":["IN-TG","IN-AP"]}'::jsonb),
  ('script:tamil', 'script', 'IN', '{"display":"Tamil","notes":"Found in Tamil Nadu (India) and Sri Lanka. Distinct combination of curves, straight lines and 90° angles. Some letters have dot-shaped diacritics.","examples":["ஹோட்டல்","உணவகம்","பள்ளி"],"regions":["IN-TN","LK"]}'::jsonb),
  ('script:odia', 'script', 'IN', '{"display":"Odia (Oriya)","notes":"Found in Odisha. Curvy look with many letters having wide semi-circles covering the top. Distinct wide curve diacritic above letters. Resembles a skull emoji shape.","examples":["ହୋଟେଲ","ରେଷ୍ଟୁରାଣ୍ଟ","ବିଦ୍ୟାଳୟ"],"regions":["IN-OR"]}'::jsonb),
  ('script:malayalam', 'script', 'IN', '{"display":"Malayalam","notes":"Found in Kerala. Somewhat simple-looking curvy letters, often containing upside-down U-shapes.","examples":["ഹോട്ടല്‍","റസ്റ്റോറന്റ്","സ്കൂള്‍"],"regions":["IN-KL"]}'::jsonb),
  ('script:meitei:manipuri', 'script', 'IN', '{"display":"Manipuri (Meitei script)","notes":"Official language of Manipur. Written using Meitei script, recognizable by its many vertical lines and right angles.","examples":["ꯍꯣꯇꯦꯜ","ꯔꯦꯁ꯭ꯇꯣꯔꯦꯟꯇ","ꯁ꯭ꯀꯨꯜ"],"regions":["IN-MN"]}'::jsonb),
  ('script:cyrillic', 'script', 'RU', '{"display":"Cyrillic","notes":"Used in Russia, Ukraine, Bulgaria, Serbia, and other Slavic countries.","examples":["Гостиница","Ресторан","Школа"]}'::jsonb),
  ('script:arabic', 'script', null, '{"display":"Arabic","notes":"Used in Middle East and North Africa. Written right-to-left, connected cursive style.","examples":["فندق","مطعم","مدرسة"]}'::jsonb),
  ('script:chinese:simplified', 'script', 'CN', '{"display":"Simplified Chinese","notes":"Used in mainland China and Singapore. Simplified form of Chinese characters.","examples":["酒店","餐厅","学校"]}'::jsonb),
  ('script:chinese:traditional', 'script', 'TW', '{"display":"Traditional Chinese","notes":"Used in Taiwan, Hong Kong, and Macau. Traditional form of Chinese characters with more strokes.","examples":["酒店","餐廳","學校"]}'::jsonb),
  ('script:japanese:hiragana', 'script', 'JP', '{"display":"Hiragana","notes":"Japanese syllabary with curved, flowing characters. Used for native Japanese words.","examples":["ホテル","レストラン","がっこう"]}'::jsonb),
  ('script:japanese:katakana', 'script', 'JP', '{"display":"Katakana","notes":"Japanese syllabary with angular characters. Used for foreign words and emphasis.","examples":["ホテル","レストラン","スクール"]}'::jsonb),
  ('script:korean:hangul', 'script', 'KR', '{"display":"Hangul","notes":"Korean alphabet with distinctive circular and linear shapes arranged in syllable blocks.","examples":["호텔","레스토랑","학교"]}'::jsonb),
  ('script:greek', 'script', 'GR', '{"display":"Greek","notes":"Used in Greece and Cyprus. Distinctive letters like Ω, Δ, Π, Σ.","examples":["Ξενοδοχείο","Εστιατόριο","Σχολείο"]}'::jsonb),
  ('script:hebrew', 'script', 'IL', '{"display":"Hebrew","notes":"Used in Israel. Written right-to-left, squared block letters.","examples":["מלון","מסעדה","בית ספר"]}'::jsonb),
  ('script:thai', 'script', 'TH', '{"display":"Thai","notes":"Used in Thailand. Rounded characters with loops and circles, no spaces between words.","examples":["โรงแรม","ร้านอาหาร","โรงเรียน"]}'::jsonb),
